<template><view class="person-card" :class="{featured}" role="button" :aria-label="'阅读'+person.name+'档案'" @tap="go('person',{id:person.id})"><view class="person-card-art"><image src="/static/river.svg" mode="aspectFill"/><text class="name-mark">{{person.name.slice(0,1)}}</text><text class="card-index">{{String(index+1).padStart(2,'0')}} / 英迹</text></view><view class="person-card-body"><text class="eyebrow">{{person.province==='待核'?'出生地域待核':person.province+' · 人物档案'}}</text><text class="person-card-name">{{person.name}}</text><text v-if="person.aliases?.length" class="alias">{{person.aliases.join(' / ')}}</text><text class="card-bio">{{person.bio}}</text><view class="card-foot"><text>走近人物</text><text>↗</text></view></view></view></template>
<script setup>import {go} from '../lib/navigation.js';defineProps({person:Object,index:{default:0},featured:Boolean})</script>
